INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000101',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Giải tích toán học — Đạo hàm, Tích phân & Giới hạn',
  'Giải tích toán học hay gọi ngắn là giải tích (Tiếng Anh: analysis) là phân nhánh của toán học làm việc với hàm liên tục, giới hạn và các lý thuyết liên quan như đạo hàm, phép lấy t...',
  'Toán học',
  'book',
  'B',
  15,
  86,
  'Giải tích toán học hay gọi ngắn là giải tích (Tiếng Anh: analysis) là phân nhánh của toán học làm việc với hàm liên tục, giới hạn và các lý thuyết liên quan như đạo hàm, phép lấy tổng, tích phân, đo lường, chuỗi vô hạn và các hàm giải tích. Những lý thuyết này thường được nghiên cứu trong trường số thực và số phức. Giải tích phát triển từ vi tích phân, từ đó phát triển các khái niệm và kỹ thuật gi',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000101',
  '[{"pageNumber":1,"text":"Giải tích toán học hay gọi ngắn là giải tích  (Tiếng Anh: analysis) là phân nhánh của toán học làm việc với hàm liên tục, giới hạn và các lý thuyết liên quan như đạo hàm, phép lấy tổng, tích phân, đo lường, chuỗi vô hạn và các hàm giải tích.\nNhững lý thuyết này thường được nghiên cứu trong trường số thực và số phức. Giải tích phát triển từ vi tích phân, từ đó phát triển các khái niệm và kỹ thuật giải tích cơ bản. Giải tích và hình học là hai nhánh riêng biệt; tuy nhiên, giải tích có thể được áp dụng cho bất kỳ không gian nào của các đối tượng toán học có định nghĩa lân cận (không gian tôpô) hoặc khoảng cách cụ thể giữa các đối tượng (không gian metric).\n\nLịch sử"},{"pageNumber":2,"text":"Cổ đại và Trung đại\nGiải tích toán học chính thức được phát triển vào thế kỷ 17 trong cuộc Cách mạng khoa học, nhưng các ý tưởng được bắt nguồn từ các nhà toán học trước đó. Các kết quả liên quan tới giải tích đã xuất hiện trong thời kỳ đầu của toán học Hy Lạp cổ đại, ví dụ như một chuỗi vô hạn được tạo ra trong nghịch lý phân đôi của Zeno. (Nói cách khác, điểm quan trọng của nghịch lý này là việc phủ định sự vô hạn của chuỗi phép tính.) Sau đó, các nhà toán học Hy Lạp như Eudoxus và Archimedes đã sử dụng các khái niệm giới hạn và hội tụ một cách rõ ràng hơn, nhưng không chính thức hơn khi họ sử dụng phương pháp vét kiệt để tính diện tích của các vùng và thể tích của vật rắn. Việc sử dụng rõ ràng các số ít vô cực xuất hiện trong Phương pháp Định lý Cơ học của Archimedes, một công trình được phát hiện lại vào thế kỷ 20. Ở châu Á, nhà toán học Trung Quốc Lưu Huy đã sử dụng phương pháp vét kiệt vào thế kỷ thứ 3 sau Công nguyên để tìm diện tích hình tròn. Tổ Xung Chi đã thiết lập một phương pháp mà sau này được gọi là nguyên lý Cavalieri để tìm thể tích của một hình cầu vào thế kỷ thứ 5. Vào thế kỷ 12, nhà toán học Ấn Độ Bhāskara II đã đưa ra các ví dụ về đạo hàm và sử dụng định lý mà ngày nay được gọi là định lý Rolle.\nTrong thế kỷ 14, Madhava của Sangamagrama đã phát triển chuỗi vô hạn mở rộng, giống như chuỗi lũy thừa và chuỗi Taylor, các hàm như sin, cosin, tan và arctan. Cùng với việc phát triển chuỗi Taylor của các hàm lượng giác, ông cũng ước tính độ lớn của các số hạng sai số được tạo ra bằng cách cắt ngắn các chuỗi này và đưa ra giá trị xấp xỉ hợp lý của một chuỗi vô hạn. Những người theo học ông tại Trường phái Thiên văn và Toán học Kerala đã mở rộng thêm các công trình của ông cho đến thế kỷ 16."},{"pageNumber":3,"text":"Cận đại và quá trình Hiện đại hóa\nCác cơ sở hiện đại của giải tích toán học đã được xác lập ở châu Âu thế kỷ 17. Descartes và Fermat đã phát triển hình học giải tích một cách độc lập với nhau, ví dụ như phương pháp xấp xỉ của Fermat đã giúp ông tìm cực trị địa phương và tiếp tuyến của các đường cong; hay tác phẩm La Geómétrie của Descartes xuất bản năm 1637 mà trong đó lần đầu tiên giới thiệu hệ tọa độ Descartes, thường được coi là thời điểm xuất hiện chính thức của giải tích toán học. Vài thập kỷ sau, Newton và Leibniz đã độc lập phát triển vi tích phân, và vi tích phân đã phát triển với các ứng dụng tiếp tục cho đến thế kỷ 18. Các ứng dụng này tập trung vào các chủ đề giải tích như tính toán các biến phân, phương trình vi phân thông thường và riêng phần, giải tích Fourier và hàm sinh. Trong thời kỳ này, kỹ thuật giải tích được áp dụng cho các bài toán rời rạc bằng cách thay thế gần đúng bằng các bài toán với các hàm liên tục.\nTrong thế kỷ thứ 18, Leonhard Euler lần đầu tiên giới thiệu kí hiệu ánh xạ. Từ đó, giải tích thực bắt đầu được phát triển một cách độc lập khi Bernand Bolzano giới thiệu khái niệm theo nghĩa hiện đại về sự liên tục vào năm 1816, nhưng người ta chỉ biết đến chúng sau năm 1870. Năm 1821, Augustin-Louis Cauchy phủ nhận các nguyên lý đại số thường được sử dụng trước đó (đặc biệt là bởi Euler) để xây dựng lại vi tích phân bằng các ý tưởng hình học và các vô cùng bé; đề ra khái niệm liên tục khi này là: sự thay đổi vô cùng bé của x sẽ dẫn tới sự thay đổi vô cùng bé cũng tương đương của y. Ông cũng đề ra khái niệm dãy Cauchy, cũng như các định lí nền tảng của giải tích phức."},{"pageNumber":4,"text":"Tham khảo\n\nLiên kết ngoài\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/Gi%E1%BA%A3i_t%C3%ADch_to%C3%A1n_h%E1%BB%8Dc (CC BY-SA 4.0)"}]'::jsonb,
  'published'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000102',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Đại số tuyến tính — Không gian vectơ & Ma trận',
  'Đại số tuyến tính là một nhánh của toán học liên quan đến các phương trình tuyến tính như: a1x1+⋯+anxn=b, ánh xạ tuyến tính như: (x1,…,xn)↦a1x1+…+anxn, và biểu diễn của chúng trong...',
  'Toán học',
  'book',
  'A',
  30,
  91,
  'Đại số tuyến tính là một nhánh của toán học liên quan đến các phương trình tuyến tính như: a1x1+⋯+anxn=b, ánh xạ tuyến tính như: (x1,…,xn)↦a1x1+…+anxn, và biểu diễn của chúng trong không gian vectơ và thông qua ma trận. Đại số tuyến tính là trung tâm của hầu hết các lĩnh vực toán học. Ví dụ, đại số tuyến tính là cơ bản trong các bài thuyết trình hiện đại về hình học, bao gồm cả việc xác định các đ',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000102',
  '[{"pageNumber":1,"text":"Đại số tuyến tính là một nhánh của toán học liên quan đến các phương trình tuyến tính như:\na1x1+⋯+anxn=b,\nánh xạ tuyến tính như:\n(x1,…,xn)↦a1x1+…+anxn,\nvà biểu diễn của chúng trong không gian vectơ và thông qua ma trận.\nĐại số tuyến tính là trung tâm của hầu hết các lĩnh vực toán học. Ví dụ, đại số tuyến tính là cơ bản trong các bài thuyết trình hiện đại về hình học, bao gồm cả việc xác định các đối tượng cơ bản như đường thẳng, mặt phẳng và phép quay. Ngoài ra, giải tích hàm, một nhánh của giải tích toán học, về cơ bản có thể được xem là ứng dụng của đại số tuyến tính vào không gian của các hàm.\nĐại số tuyến tính cũng được sử dụng trong hầu hết các ngành khoa học và lĩnh vực kỹ thuật, vì nó cho phép mô hình hóa nhiều hiện tượng tự nhiên và tính toán hiệu quả với các mô hình như vậy. Đối với các hệ thống phi tuyến, không thể được mô hình hóa bằng đại số tuyến tính, nó thường được sử dụng để xử lý các phép xấp xỉ bậc nhất, do thực tế là vi phân của một hàm đa biến tại một điểm là ánh xạ tuyến tính gần đúng nhất của hàm gần điểm đó.\nĐại số tuyến tính được sử dụng nhiều trong toán học, như trong đại số đại cương, giải tích hàm, hình học giải tích... để giải các bài toán như phép quay trong không gian, nội suy bình phương nhỏ nhất, nghiệm của hệ phương trình vi phân, tìm đường tròn qua ba điểm... Nó cũng có vô vàn ứng dụng trong khoa học tự nhiên (vật lý, công nghệ...) và khoa học xã hội (kinh tế...), vì các mô hình phi tuyến tính hay gặp trong tự nhiên và xã hội thường có thể xấp xỉ bằng mô hình tuyến tính."},{"pageNumber":2,"text":"Lịch sử\nQuy trình giải các phương trình tuyến tính đồng thời, ngày nay được gọi là phép khử Gauss xuất hiện trong văn bản toán học Trung Quốc cổ đại Chương 8: Mảng chữ nhật trong Cửu chương toán thuật. Việc sử dụng nó được minh họa trong 18 bài toán, với 2 đến 5 phương trình.\nHệ phương trình tuyến tính phát sinh ở châu Âu với sự ra đời năm 1637 hệ tọa độ trong hình học do René Descartes đưa ra. Thực tế, trong hình học mới này, ngày nay được gọi là hình học Descartes, các đường thẳng và mặt phẳng được biểu diễn bằng các phương trình tuyến tính, và việc tính toán các giao điểm của chúng biến thành việc giải các hệ phương trình tuyến tính.\nCác phương pháp hệ thống đầu tiên để giải hệ thống tuyến tính sử dụng các định thức, được Leibniz xem xét lần đầu tiên vào năm 1693. Năm 1750, Gabriel Cramer sử dụng chúng để đưa ra các giải pháp rõ ràng của hệ thống tuyến tính, ngày nay được gọi là quy tắc Cramer. Sau đó, Gauss mô tả thêm phương pháp loại trừ, phương pháp này ban đầu được coi là một tiến bộ trong ngành trắc địa.\nNăm 1844, Hermann Grassmann xuất bản \"Lý thuyết mở rộng\" bao gồm các chủ đề mới cơ bản về cái mà ngày nay được gọi là đại số tuyến tính. Năm 1848, James Joseph Sylvester đưa ra thuật ngữ ma trận.\nĐại số tuyến tính phát triển với những ý tưởng được ghi nhận trong mặt phẳng phức. Ví dụ: hai số w và z trong ℂ có sự khác biệt w−z, và các đoạn thẳng wz‾ và 0(w−z)‾ có cùng chiều dài và hướng. Các phân đoạn này là tương đương nhau. Hệ thống bốn chiều ℍ của các quaternion được bắt đầu vào năm 1843. Thuật ngữ vectơ được giới thiệu là v=xi+yj+zk đại diện cho một điểm trong không gian. Chênh lệch bậc bốn p−q cũng tạo ra một đoạn tương đương với pq‾. Các hệ thống số siêu phức khác cũng sử dụng ý tưởng về một không gian tuyến tính có cơ sở.\nArthur Cayley đã giới thiệu phép nhân ma trận và ma trận nghịch đảo vào năm 1856, làm cho nhóm tuyến tính tổng quát trở nên khả thi. Cơ chế biểu diễn nhóm đã có sẵn để các nhà toán học mô tả các số phức và siêu phức. Điều quan trọng nhất là Cayley sử dụng một chữ cái duy nhất để biểu thị một ma trận, do đó coi ma trận như một đối tượng tổng hợp. Ông cũng nhận ra mối liên hệ giữa ma trận và định thức, và viết \"Sẽ có nhiều điều để nói về lý thuyết ma trận này, theo tôi, có vẻ như, có trước lý thuyết về định thức\".\nBenjamin Peirce đã xuất bản tác phẩm Đại số liên kết tuyến tính của mình (1872), và con trai của ông là Charles Sanders Peirce đã mở rộng tác phẩm này sau đó.\nĐiện báo yêu cầu một hệ thống vật lý giải thích nó, và ấn phẩm năm 1873 có tên Một luận thuyết về điện và từ trường đã thiết lập một lý thuyết trường về lực và yêu cầu hình học vi phân để biểu thị. Đại số tuyến tính là hình học vi phân phẳng và phục vụ trong không gian tiếp tuyến với đa tạp. Đối xứng điện từ của không thời gian được biểu thị bằng các phép biến đổi Lorentz, và phần lớn lịch sử của đại số tuyến tính là lịch sử của các phép biến đổi Lorentz.\nĐịnh nghĩa hiện đại và chính xác hơn đầu tiên của không gian vectơ được Peano đưa ra vào năm 1888; đến năm 1900, một lý thuyết về các phép biến đổi tuyến tính của không gian vectơ hữu hạn chiều đã xuất hiện. Đại số tuyến tính có hình thức hiện đại vào nửa đầu thế kỷ XX, khi nhiều ý tưởng và phương pháp của các thế kỷ trước được khái quát hóa thành đại số trừu tượng. Sự phát triển của máy tính dẫn đến việc tăng cường nghiên cứu các thuật toán hiệu quả để loại bỏ Gaussian và phân rã ma trận, và đại số tuyến tính trở thành một công cụ thiết yếu để mô hình hóa và mô phỏng."},{"pageNumber":3,"text":"Phạm vi nghiên cứu\n\nKhông gian vectơ\nCấu trúc chính của đại số tuyến tính là các không gian vectơ. Một không gian vectơ trên trường số 𝔽 là một tập V kèm theo phép toán hai ngôi. Các phần tử trong V gọi là những vectơ, các phần tử trong 𝔽 gọi là vô hướng. Phép toán đầu tiên là phép cộng vectơ, cộng 2 vectơ v và w cho ra một vectơ thứ 3 là v+w. Phép toán thứ hai là phép nhân một vô hướng a với bất kỳ vectơ v nào và kết quả cho ra một vectơ mới av, phép toán này gọi là phép nhân vô hướng của v với a. Các phép nhân và cộng trong không gian vectơ phải thỏa mãn 8 tiên đề sau, với u, v và w là các vectơ trong tập V. a và b là các vô hướng trong trường số 𝔽.\n\nÁnh xạ tuyến tính\nCho 2 không gian vectơ V và W trên trường 𝔽, một biến đổi tuyến tính (còn gọi là ánh xạ tuyến tính) là một ánh xạ:\n\nT:V→W\nbảo toàn phép cộng và phép nhân vô hướng:\n\nT(u+v)=T(u)+T(v),T(av)=aT(v)\nvới mọi vectơ u,v∈V và mọi vô hướng a∈𝔽.\n\nCác chủ đề chính\nĐịnh thức\nĐộc lập tuyến tính\nHệ phương trình tuyến tính\nLý thuyết Lie\nMa trận\nVĩnh thức"},{"pageNumber":4,"text":"Giới thiệu chung\nTrong trường đại học, đại số tuyến tính bắt đầu từ nghiên cứu các vectơ trong hệ tọa độ Descartes 2 chiều hoặc 3 chiều. Các vectơ là các đoạn thẳng có hướng và độ lớn. Các kết quả trong không gian 2 hoặc 3 chiều có thể được mở rộng ra cho nhiều chiều hơn, gọi tổng quát là không gian vectơ.\nKhông gian vectơ là một khái niệm trừu tượng của đại số trừu tượng, được định nghĩa trên một trường toán học, phổ biến trong ứng dụng là trường số thực hoặc trường số phức.\nCác biến đổi tuyến tính chuyển các phần tử trong một không gian vectơ này sang không gian vectơ kia, tuân thủ phép cộng và phép nhân vô hướng. bản thân tập hợp của các biến đổi này cũng hình thành nên không gian vectơ của chính chúng.\nNếu hệ cơ sở của một không gian vectơ là cố định, mọi biến đổi tuyến tính đều có thể viết thành bảng gọi là ma trận. Việc nghiên cứu các tính chất của ma trận, như định thức và vectơ riêng là một phần quan trọng của đại số tuyến tính.\nSử dụng đại số tuyến tính có thể giải chính xác hoặc gần đúng rất nhiều bài toán, bao gồm cả các bài toán không tuyến tính. Lý do là ta luôn có thể sử dụng vi giải tích để biến các hàm không tuyến tính thành gần đúng tuyến tính ở gần những điểm quan tâm. Phương pháp này là một trong những phương pháp phổ biến nhất trong toán học ứng dụng vào khoa học và kỹ thuật."},{"pageNumber":5,"text":"Một số định lý quan trọng\nMọi không gian véc tơ đều có một hệ cơ sở.\nMột ma trận A vuông cỡ n được gọi là khả nghịch nếu tồn tại ma trận vuông B cỡ n thoả mãn AB=BA=I với I là ma trận đơn vị cùng cỡ với A.\nVới một ma trận A vuông cỡ n, các mệnh đề sau đây là tương đương (tức là luôn cùng đúng hoặc cùng sai)\nA khả nghịch\ndet⁡(A)≠0.\nrank A=n.\nnull A=0.\nA không có giá trị riêng bằng 0.\nVới mọi 𝐛, A𝐱=𝐛 có duy nhất một nghiệm 𝐱.\nATA khả nghịch.\nCác hàng (hoặc cột) của A tạo nên các vectơ độc lập tuyến tính trong không gian vectơ của A.\n\nXem thêm\nVectơ\nMa trận\nĐịnh thức\nBiến đổi tuyến tính\nĐại số trừu tượng\nBài toán quy hoạch tuyến tính\n\nChú thích\n\nGhi chú\n\nLiên kết ngoài\n\n Tư liệu liên quan tới Linear algebra tại Wikimedia Commons\nWeisstein, Eric W., \"Linear Algebra\", MathWorld.\nLinear algebra (mathematics) tại Encyclopædia Britannica (bằng tiếng Anh)\nStrang,Gilbert, Linear Algebra and Its Applications (4th Edition), 2006\nBanerjee, Sudipto; Roy, Anindya, Linear Algebra and Matrix Analysis for Statistics (Chapman & Hall/CRC Texts in Statistical Science), 2014\nGrassmann, Hermann, Die lineare Ausdehnungslehre dargestellt und durch Anwendungen auf die übrigen Zweige der Mathematik, wie auch auf die Statik, Mechanik, die Lehre vom Magnetismus und die Krystallonomie, 1844.\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/%C4%90%E1%BA%A1i_s%E1%BB%91_tuy%E1%BA%BFn_t%C3%ADnh (CC BY-SA 4.0)"}]'::jsonb,
  'published'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000103',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Cấu trúc dữ liệu & Nguyên lý lưu trữ hiệu quả',
  'Trong khoa học máy tính, cấu trúc dữ liệu là một cách lưu dữ liệu trong máy tính sao cho nó có thể được sử dụng một cách hiệu quả. Trong thiết kế nhiều loại chương trình, việc chọn...',
  'Công nghệ thông tin',
  'book',
  'A',
  30,
  92,
  'Trong khoa học máy tính, cấu trúc dữ liệu là một cách lưu dữ liệu trong máy tính sao cho nó có thể được sử dụng một cách hiệu quả. Trong thiết kế nhiều loại chương trình, việc chọn cấu trúc dữ liệu là vấn đề quan trọng. Kinh nghiệm trong việc xây dựng các hệ thống lớn cho thấy khó khăn của việc triển khai chương trình, chất lượng và hiệu năng của kết quả cuối cùng phụ thuộc rất nhiều vào việc chọn',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000103',
  '[{"pageNumber":1,"text":"Trong khoa học máy tính, cấu trúc dữ liệu là một cách lưu dữ liệu trong máy tính sao cho nó có thể được sử dụng một cách hiệu quả.\nTrong thiết kế nhiều loại chương trình, việc chọn cấu trúc dữ liệu là vấn đề quan trọng. Kinh nghiệm trong việc xây dựng các hệ thống lớn cho thấy khó khăn của việc triển khai chương trình, chất lượng và hiệu năng của kết quả cuối cùng phụ thuộc rất nhiều vào việc chọn cấu trúc dữ liệu tốt nhất.\nMỗi loại cấu trúc dữ liệu phù hợp với một vài loại ứng dụng khác nhau, một số cấu trúc dữ liệu dành cho những công việc đặc biệt. Ví dụ, các B-tree đặc biệt phù hợp trong việc thiết kế cơ sở dữ liệu. Sau khi cấu trúc dữ liệu được chọn, người ta thường dễ nhận thấy thuật toán cần sử dụng. Đôi khi trình tự công việc diễn ra theo thứ tự ngược lại: cấu trúc dữ liệu được chọn do những bài toán quan trọng nhất định có thuật toán chạy tốt nhất với một số cấu trúc dữ liệu cụ thể. Trong cả hai trường hợp, việc lựa chọn cấu trúc dữ liệu là rất quan trọng."},{"pageNumber":2,"text":"Tổng quan\nThông thường, một cấu trúc dữ liệu được chọn cẩn thận sẽ cho phép thực hiện thuật toán hiệu quả hơn. Việc chọn cấu trúc dữ liệu thường bắt đầu từ chọn một cấu trúc dữ liệu trừu tượng. Một cấu trúc dữ liệu được thiết kế tốt cho phép thực hiện nhiều phép toán, sử dụng càng ít tài nguyên, thời gian xử lý và không gian bộ nhớ càng tốt. Các cấu trúc dữ liệu được triển khai bằng cách sử dụng các kiểu dữ liệu, các tham chiếu và các phép toán trên đó được cung cấp bởi một ngôn ngữ lập trình.\nTri thức đó đã dẫn đến sự nổi lên của nhiều ngôn ngữ lập trình và phương pháp thiết kế được hình thức hóa, mà trong đó, nhân tố tổ chức quan trọng là các cấu trúc dữ liệu chứ không phải các thuật toán. Đa số ngôn ngữ có một tính năng thuộc dạng hệ thống module cho phép các cấu trúc dữ liệu được tái sử dụng an toàn trong các ứng dụng khác nhau, bằng cách dùng các giao diện có điều khiển để che các chi tiết cài đặt đã được kiểm thử. Đặc biệt, các ngôn ngữ lập trình hướng đối tượng như C++ và Java sử dụng lớp (class) cho mục đích này.\nVì cấu trúc dữ liệu có tính chất quyết định đối với các chương trình chuyên nghiệp nên có rất nhiều hỗ trợ về cấu trúc dữ liệu trong các thư viện chuẩn của các ngôn ngữ lập trình hiện đại, ví dụ thư viện mẫu chuẩn của C++, Java API, và Microsoft .NET Framework.\nCác cấu trúc xây dựng căn bản của hầu hết các cấu trúc dữ liệu là mảng (array), bản ghi (record), tổ hợp phân biệt(?) (discriminated union), và tham chiếu (reference). Ví dụ, tham chiếu khả rỗng (có thể có giá trị null) là một kết hợp của tham chiếu và cấu trúc discriminated union, và cấu trúc dữ liệu liên kết đơn giản nhất, danh sách liên kết, được xây dựng từ các bản ghi và các tham chiếu khả rỗng."},{"pageNumber":3,"text":"Các nguyên tắc cơ bản\n\nNgôn ngữ hỗ trợ\nHầu hết hợp ngữ và những ngôn ngữ lập trình cấp thấp, chẳng hạn BCPL (Basic Combined Programming Language), không hỗ trợ sẵn cấu trúc dữ liệu. Ngôn ngữ lập trình ở cấp cao và một số hợp ngữ ở mức cao có những cú pháp hay chức năng sẵn có hỗ trợ những cấu trúc dữ liệu nhất định như là bản ghi và mảng. Ví dụ ngôn ngữ C và Pascal hỗ trợ kiểu cấu trúc và bản ghi bên cạnh hỗ trợ mảng một chiều và mảng đa chiều.\nHầu hết những ngôn ngữ lập trình đều có những thư viện có sẵn, hỗ trợ việc xây dựng cấu trúc dữ liệu, chẳng hạn bộ thư viện chuẩn C++, Java Collections Framework và .Net Framework.\n\nCác cấu trúc dữ liệu thường dùng\nMảng (cấu trúc dữ liệu) (array list)\nNgăn xếp (stack)\nHàng đợi (queue)\nBảng băm (hash table)\nDanh sách liên kết (linked list)\nCây (cấu trúc dữ liệu) (tree)\nĐồ thị (cấu trúc dữ liệu) (graph)\n\nXem thêm\nDanh sách các cấu trúc dữ liệu\nMô hình dữ liệu\nDanh sách liên kết\n\nTham khảo\n\nĐọc thêm\nPeter Brass, Advanced Data Structures, Cambridge University Press, 2008.\nDonald Knuth, The Art of Computer Programming, vol. 1. Addison-Wesley, 3rd edition, 1997.\nDinesh Mehta and Sartaj Sahni Handbook of Data Structures and Applications, Chapman and Hall/CRC Press, 2007.\nNiklaus Wirth, Algorithms and Data Structures, Prentice Hall, 1985.\n\nLiên kết ngoài"},{"pageNumber":4,"text":"UC Berkeley video course on data structures\nDescriptions from the Dictionary of Algorithms and Data Structures\nCSE.unr.edu\nData structures course with animations\nData structure tutorials with animations Lưu trữ ngày 18 tháng 6 năm 2012 tại Wayback Machine\nAn Examination of Data Structures from.NET perspective\nSchaffer, C. Data Structures and Algorithm Analysis\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/C%E1%BA%A5u_tr%C3%BAc_d%E1%BB%AF_li%E1%BB%87u (CC BY-SA 4.0)"}]'::jsonb,
  'published'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000104',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Lý thuyết xác suất & Không gian biến cố',
  'Lý thuyết xác suất là ngành toán học chuyên nghiên cứu xác suất. Các nhà toán học coi xác suất là các số trong khoảng [0,1], được gán tương ứng với một biến cố mà khả năng xảy ra h...',
  'Toán học',
  'book',
  'B',
  15,
  85,
  'Lý thuyết xác suất là ngành toán học chuyên nghiên cứu xác suất. Các nhà toán học coi xác suất là các số trong khoảng [0,1], được gán tương ứng với một biến cố mà khả năng xảy ra hoặc không xảy ra là ngẫu nhiên. Ký hiệu xác suất P(E) được gán cho biến cố E theo tiên đề xác suất. Xác suất mà biến cố E xảy ra khi biết việc xảy ra của biến cố F là một xác suất có điều kiện của E khi biết F; giá trị s',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000104',
  '[{"pageNumber":1,"text":"Lý thuyết xác suất là ngành toán học chuyên nghiên cứu xác suất.\nCác nhà toán học coi xác suất là các số trong khoảng [0,1], được gán tương ứng với một biến cố mà khả năng xảy ra hoặc không xảy ra là ngẫu nhiên. Ký hiệu xác suất P(E) được gán cho biến cố E theo tiên đề xác suất.\nXác suất mà biến cố E xảy ra khi biết việc xảy ra của biến cố F là một xác suất có điều kiện của E khi biết F; giá trị số của nó là P(E∩F)/P(F) (với điều kiện là P(F) khác 0). Nếu xác suất có điều kiện của E khi biết F là bằng với xác suất (\"không có điều kiện\")của E, thì E và F được xem là các sự kiện độc lập. Vì quan hệ giữa E và F là đối xứng nên ta có thể nói rằng\nP(E∩F)=P(E)P(F).\nHai khái niệm chủ đạo trong lý thuyết xác suất là biến ngẫu nhiên và phân bố xác suất của một biến ngẫu nhiên; xem thông tin cụ thể ở các bài tương ứng.\n\nMột cái nhìn trừu tượng về xác suất\nCác nhà toán học \"thuần túy\" thường xem lý thuyết xác suất là ngành nghiên cứu về các biến ngẫu nhiên và không gian xác suất — hướng này được đưa ra bởi Kolmogorov vào thập niên 1930. Một không gian xác suất là một bộ ba (Ω,ℱ,P), trong đó:"},{"pageNumber":2,"text":"Ω là tập không rỗng, đôi khi gọi là \"không gian mẫu\", trong đó mỗi thành viên của nó được coi là một kết quả có thể xảy ra của một thực nghiệm ngẫu nhiên. Ví dụ, nếu chọn ngẫu nhiên 100 cử tri trong số các cử tri tại California và hỏi họ sẽ bầu cho ai vào chức vụ thống đốc, thì tập tất cả các dãy gồm 100 cử tri California sẽ là không gian mẫu Ω.\nℱ là một σ-đại số của các tập con của Ω, các thành viên của nó được gọi là các \"biến cố\". Ví dụ, tập tất cả các chuỗi gồm 100 cử tri California trong đó ít nhất 60 người sẽ bầu cho Schwarzenegger được xem là \"biến cố\" rằng ít nhất 60 trong số 100 người được chọn sẽ bầu cho Schwarzenegger. Nói rằng ℱ là một σ-đại số có nghĩa rằng, theo định nghĩa, nó chứa Ω, rằng phần bù của một biến cố bất kì là một biến cố, và rằng hợp của một chuỗi (hữu hạn hay vô hạn đếm được) các biến cố bất kì là một biến cố.\nP là một độ đo (cụ thể là độ đo xác suất) trên Ω, nghĩa là ℱ=ℙ(Ω), đó là một σ-đại số và là đại số lớn nhất mà ta có thể tạo được bằng Ω.\nDo đó, trong một không gian rời rạc, ta có thể bỏ qua ℱ và chỉ viết (Ω,P) khi định nghĩa nó.\nMặt khác, nếu Ω không đếm được và ta dùng ℱ=ℙ(Ω), ta sẽ gặp rắc rối khi định nghĩa phép đo xác suất P vì ℱ quá lớn, nghĩa là sẽ có các tập mà không thể gán cho nó một độ đo duy nhất, ví dụ Banach-Tarski Paradox. Do đó, ta phải dùng một σ-đại số ℱ nhỏ hơn (ví dụ. đại số Borel của Ω là σ-đại số nhỏ nhất có thể làm cho tất cả các tập mở trở nên đo được).\nMột biến ngẫu nhiên X là một measurable function (hàm đo được) trên Ω.\nVí dụ, số cử tri sẽ bầu cho Schwarzenegger trong mẫu 100 người là một biến ngẫu nhiên.\nNếu X là biến ngẫu nhiên bất kì, ký hiệu P(X≥60), viết tắt của P({ω∈Ω∣X(ω)≥60}), là xác suất của \"biến cố\" X≥60.\nVề các phương pháp đại số khác với cách tiếp cận của Kolmogorov, mời xem bài algebra of random variables."},{"pageNumber":3,"text":"Triết lý trong ứng dụng của xác suất\nMột số nhà thống kê chỉ gán các xác suất cho các biến cố ngẫu nhiên, ví dụ, các biến ngẫu nhiên, mà cho kết quả thử nghiệm thực hay mang tính lý thuyết; đó là những nhà tần suất học (frequentist).Một số khác lại gán xác suất với những mệnh đề không chắc chắn, tùy theo mức độ chủ quan (personal probability) tin vào sự đúng đắn của nó. Những người như vậy là các nhà Bayes. Một nhà Bayes có thể gán một xác suất cho một mệnh đề như ''đã từng có sự sống trên Sao Hỏa một tỉ năm trước,'' vì điều đó là không chắc chắn, trong khi một nhà tần suất học sẽ không gán xác suất cho những phát biểu ngẫu nhiên như vậy. Một nhà tần suất học có thể xem lời tuyên bố đó là không có ý nghĩa. Các nhà tần suất học chỉ gán xác suất cho kết quả của những thử nghiệm ngẫu nhiên được định nghĩa tốt, nghĩa là, khi có một không gian mẫu định sẵn. Trong kinh tế, xác suất đóng góp rất nhiều cho việc tính toán và đưa ra các giải pháp nghiên cứu thị trường,...\n\nXem thêm\nThuật ngữ xác suất và thống kê\nCác chủ đề về xác suất\nCác chủ đề về thống kê\nCác bài viết về thống kê\nMô hình hóa dự báo\nLý thuyết đo mờ\nXác suất\nTiên đề xác suất\nPhân bố xác suất\nGiá trị kì vọng\nLikelihood function\nBiến ngẫu nhiên\nKhông gian mẫu\nPhương sai\nĐộc lập thống kê\nKhái niệm trong xác suất\nLý thuyết khả năng"},{"pageNumber":4,"text":"Thư mục\nPierre Simon de Laplace (1812) Analytical Theory of Probability\nThe first major treatise blending calculus with probability theory, originally in French: Theorie Analytique des Probabilités.\nAndrei Nikolajevich Kolmogorov (1933) Foundations of the Theory of Probability\nThe modern measure-theoretic foundation of probability theory, originally in German: Grundbegriffe der Wahrscheinlichkeitrechnung.\nHarold Jeffreys (1939) The Theory of Probability\nAn empiricist, Bayesian approach to the foundations of probability theory.\nEdward Nelson (1987) Radically Elementary Probability Theory\nDiscrete foundations of probability theory, based on nonstandard analysis and internal set theory. downloadable. http://www.math.princeton.edu/~nelson/books.html\nPatrick Billingsley: Probability and Measure, John Wiley and Sons, New York, Toronto, London, 1979.\n\nTham khảo\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/L%C3%BD_thuy%E1%BA%BFt_x%C3%A1c_su%E1%BA%A5t (CC BY-SA 4.0)"}]'::jsonb,
  'published'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000105',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Kinh tế học vi mô — Cung cầu & Cân bằng thị trường',
  'Kinh tế học vi mô hay là kinh tế tầm nhỏ (Tiếng Anh: microeconomics), là một phân ngành của kinh tế học chuyên nghiên cứu về đặc điểm, cấu trúc và hành vi của cả một nền kinh tế nó...',
  'Kinh tế',
  'paper',
  'C',
  5,
  78,
  'Kinh tế học vi mô hay là kinh tế tầm nhỏ (Tiếng Anh: microeconomics), là một phân ngành của kinh tế học chuyên nghiên cứu về đặc điểm, cấu trúc và hành vi của cả một nền kinh tế nói chung. Kinh tế học vĩ mô và kinh tế học vi mô là hai lĩnh vực chung nhất của kinh tế học. Trong khi kinh tế học vi mô chủ yếu nghiên cứu về hành vi của các cá thể đơn lẻ, như công ty và cá nhân người tiêu dùng, kinh tế',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000105',
  '[{"pageNumber":1,"text":"Kinh tế học vi mô hay là kinh tế tầm nhỏ   (Tiếng Anh: microeconomics), là một phân ngành của kinh tế học chuyên nghiên cứu về đặc điểm, cấu trúc và hành vi của cả một nền kinh tế nói chung. Kinh tế học vĩ mô và kinh tế học vi mô là hai lĩnh vực chung nhất của kinh tế học. Trong khi kinh tế học vi mô chủ yếu nghiên cứu về hành vi của các cá thể đơn lẻ, như công ty và cá nhân người tiêu dùng, kinh tế học vĩ mô lại nghiên cứu các chỉ tiêu cộng hưởng như GDP, tỉ lệ thất nghiệp, và các chỉ số giá cả để hiểu cách hoạt động của cả nền kinh tế.\n\nMục tiêu nghiên cứu\nMột trong những mục tiêu nghiên cứu của kinh tế vi mô là phân tích cơ chế thị trường thiết lập ra giá cả tương đối giữa các mặt hàng và dịch vụ và sự phân phối các nguồn tài nguyên giới hạn giữa nhiều cách sử dụng khác nhau. Kinh tế vi mô phân tích thất bại của thị trường, khi thị trường không vận hành hiệu quả, cũng như miêu tả những điều kiện cần có trong lý thuyết cho việc cạnh tranh hoàn hảo. Những ngành quan trọng trong kinh tế vi mô bao gồm thị trường dưới thông tin bất đối xứng, chọn lựa với sự không chắc chắn và các áp dụng trong kinh tế của lý thuyết trò chơi.\n\nPhạm vi nghiên cứu\nPhạm vi nghiên cứu của kinh tế học vi mô bao gồm:"},{"pageNumber":2,"text":"Các lý luận cơ bản cho kinh tế học như cung, cầu, giá cả, thị trường\nCác lý thuyết về hành vi của người tiêu dùng\nLý thuyết về hành vi của người sản xuất\nCấu trúc thị trường\nThị trường cạnh tranh hoàn hảo\nThị trường cạnh tranh mang tính độc quyền\nThị trường thiểu số độc quyền\nThị trường độc quyền thuần túy\nThị trường các yếu tố sản xuất: Lao động - Vốn - Tài nguyên\nVai trò của Chính phủ trong nền kinh tế thị trường\nCác lý luận về trao đổi, phúc lợi kinh tế\nCác lý luận về thất bại thị trường\n\nPhương pháp nghiên cứu\nPhương pháp nghiên cứu của kinh tế học vi mô bao gồm:\n\nPhương pháp mô hình hóa\nXây dựng mô hình.\nPhát triển mô hình bằng cách phân tích dựa trên các dữ liệu thu thập được.\nKiểm chứng thực tế.\n\nPhương pháp so sánh tĩnh\nTheo phương pháp này, các giả thuyết kinh tế về mối quan hệ giữa các biến luôn phải đi kèm với giả định Ceteris Paribus trong mô hình."},{"pageNumber":3,"text":"Phương pháp phân tích biên tế\nĐây là phương pháp đặc thù của Kinh tế học nói chung và Kinh tế học vi mô nói riêng. Nó cũng là phương pháp của sự lựa chọn kinh tế tối ưu bởi vì bất cứ sự lựa chọn nào cũng phải dựa trên sự so sánh giữa lơi ích mang lại và chi phí bỏ ra. Phương pháp phân tích biên tế được sử dụng để tìm ra điểm tối ưu (còn gọi là điểm cân bằng) của sự lựa chọn. Theo phương pháp này, chúng ta phải so sánh lợi ích và chi phí tại mỗi đơn vị hàng hóa, dịch vụ được sản xuất (hoặc tiêu dùng) tăng thêm. Lợi ích chi phí đó được gọi là lợi ích biên tế và chi phi biên tế.\nPhương pháp này còn được biết đến với tên gọi: phương pháp phân tích cận biên.\n\nNền tảng cho các chuyên ngành của kinh tế học\nKinh tế học vi mô là nền tảng cho nhiều chuyên ngành của kinh tế học. Chủ nghĩa kinh tế tự do mới phát triển các lý luận kinh tế học vĩ mô của mình trên cơ sở kinh tế học vi mô. Ngay cả chủ nghĩa Keynes gần đây (phái kinh tế học Keynes mới) cũng đi tìm các cơ sở kinh tế học vi mô cho lý luận kinh tế học vĩ mô của chủ nghĩa này. Trên cơ sở kinh tế học vĩ mô, nhiều chuyên ngành khác trong đó có tài chính quốc tế, kinh tế học phát triển được phát triển. Kinh tế học vi mô còn làm nền tảng trực tiếp cho các môn như kinh tế học công cộng, kinh tế học phúc lợi, thương mại quốc tế, lý thuyết tổ chức ngành, địa lý kinh tế, v.v...\nCùng với kinh tế vĩ mô là hai trụ cột của khoa học kinh tế."},{"pageNumber":4,"text":"Chú thích\n\nTham khảo\nNguyễn Đại Thắng (2005), Giáo trình Kinh tế học vi mô, Nhà xuất bản Khoa học và Kỹ thuật, Hà Nội.\nHal R. Varian (1999), Intermediate Microeconomics: A Modern Approach, Fifth Edition, W. W. Norton and Company.\nRobert S. Pyndyck and Daniel L. Rubinfeld (1994), Kinh tế học vi mô, Nhà xuất bản Khoa học và Kỹ thuật, Hà Nội.\nSamuelson - Kinh te học\nGiáo trình kinh tế học vi mô - Bộ giáo dục & đào tạo - trường ĐH kinh tế quốc dân - Chủ biên: PGS. TS Vũ Kim Dũng\nGiáo trình kinh tế vi mô - Đại học kinh tế - Đại học Quốc gia Hà Nội"},{"pageNumber":5,"text":"Đọc thêm\nBade, Robin (2001). Foundations of Microeconomics. Michael Parkin. Addison Wesley Paperback 1st Edition.\nColander, David. Microeconomics. McGraw-Hill Paperback, 7th Edition: 2008.\nDunne, Timothy, J. Bradford Jensen, and Mark J. Roberts (2009). Producer Dynamics: New Evidence from Micro Data. University of Chicago Press. ISBN 9780226172569.{{Chú thích sách}}:  Quản lý CS1: nhiều tên: danh sách tác giả (liên kết)\nEaton, B. Curtis; Eaton, Diane F.; and Douglas W. Allen. Microeconomics. Prentice Hall, 5th Edition: 2002.\nFrank, Robert A.; Microeconomics and Behavior. McGraw-Hill/Irwin, 6th Edition: 2006.\nFriedman, Milton. Price Theory. Aldine Transaction: 1976\nJehle, Geoffrey A.; and Philip J. Reny. Advanced Microeconomic Theory. Addison Wesley Paperback, 2nd Edition: 2000.\nHagendorf, Klaus: Labour Values and the Theory of the Firm. Part I: The Competitive Firm. Paris: EURODOS; 2009.\nHicks, John R. Value and Capital. Clarendon Press. [1939] 1946, 2nd ed.\nKatz, Michael L.; and Harvey S. Rosen. Microeconomics. McGraw-Hill/Irwin, 3rd Edition: 1997.\nKreps, David M. A Course in Microeconomic Theory. Princeton University Press: 1990\nLandsburg, Steven. Price Theory and Applications. South-Western College Pub, 5th Edition: 2001.\nMankiw, N. Gregory. Principles of Microeconomics. South-Western Pub, 2nd Edition: 2000.\nMas-Colell, Andreu; Whinston, Michael D.; and Jerry R. Green. Microeconomic Theory. Oxford University Press, US: 1995.\nMcGuigan, James R.; Moyer, R. Charles; and Frederick H. Harris. Managerial Economics: Applications, Strategy and Tactics. South-Western Educational Publishing, 9th Edition: 2001.\nNicholson, Walter. Microeconomic Theory: Basic Principles and Extensions. South-Western College Pub, 8th Edition: 2001.\nPerloff, Jeffrey M. Microeconomics. Pearson - Addison Wesley, 4th Edition: 2007.\nPerloff, Jeffrey M. Microeconomics: Theory and Applications with Calculus. Pearson - Addison Wesley, 1st Edition: 2007\nPindyck, Robert S.; and Daniel L. Rubinfeld. Microeconomics. Prentice Hall, 7th Edition: 2008.\nRuffin, Roy J.; and Paul R. Gregory. Principles of Microeconomics. Addison Wesley, 7th Edition: 2000.\nVarian, Hal R. (1987). \"microeconomics,\" The New Palgrave: A Dictionary of Economics, v. 3, pp. 461–63.\nVarian, Hal R. Intermediate Microeconomics. W.W. Norton & Company, 7th Edition.\nVarian, Hal R. Microeconomic Analysis. W. W. Norton & Company, 3rd Edition."},{"pageNumber":6,"text":"Xem thêm\nKinh tế học vĩ mô\n\nLiên kết ngoài\nAmosWEB GLOSS*arama - online economics dictionary\nA free textbook of microeconomics, supplemented by software and data - Key concepts of microeconomics easily explained and thoroughly criticised.\nSmartalec Economic Discussion Board: [1] Lưu trữ ngày 12 tháng 3 năm 2007 tại Wayback Machine - Growing community for Economic discussion.\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/Kinh_t%E1%BA%BF_h%E1%BB%8Dc_vi_m%C3%B4 (CC BY-SA 4.0)"}]'::jsonb,
  'published'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.know_inherit_listings (id, author_id, author_name, title, summary, subject, doc_type, tier, price, ai_quality_score, preview_content, full_content_url, pages, status)
VALUES (
  '00000000-0000-4000-8000-000000000106',
  NULL,
  'Wikipedia Tiếng Việt (CC BY-SA 4.0)',
  'Các định luật chuyển động của Newton',
  'Các định luật về chuyển động của Newton là một hệ thống gồm 3 định luật đặt nền móng cơ bản cho cơ học cổ điển. Chúng mô tả mối quan hệ giữa sự chuyển động của một vật thể và các l...',
  'Vật lý',
  'paper',
  'C',
  5,
  80,
  'Các định luật về chuyển động của Newton là một hệ thống gồm 3 định luật đặt nền móng cơ bản cho cơ học cổ điển. Chúng mô tả mối quan hệ giữa sự chuyển động của một vật thể và các lực tác động lên vật thể đó. Các định luật đã được diễn giải theo nhiều cách khác nhau trong suốt 8 thế kỷ sau đó, và có thể tóm tắt như sau: Định luật I (Định luật quán tính): Một vật không chịu tác dụng của một lực nào',
  'supabase://know_inherit/00000000-0000-4000-8000-000000000106',
  '[{"pageNumber":1,"text":"Các định luật về chuyển động của Newton là một hệ thống gồm 3 định luật đặt nền móng cơ bản cho cơ học cổ điển. Chúng mô tả mối quan hệ giữa sự chuyển động của một vật thể và các lực tác động lên vật thể đó. Các định luật đã được diễn giải theo nhiều cách khác nhau trong suốt 8 thế kỷ sau đó, và có thể tóm tắt như sau:"},{"pageNumber":2,"text":"Định luật I (Định luật quán tính): Một vật không chịu tác dụng của một lực nào hoặc chịu tác dụng của các lực có hợp lực bằng 0, hay còn nói cách khác là các lực cân bằng thì nó vẫn giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều mãi mãi.\nĐịnh luật II: Vector gia tốc của một vật luôn cùng hướng với lực tác dụng lên vật. Độ lớn của vector gia tốc tỉ lệ thuận với độ lớn của vector lực và tỉ lệ nghịch với khối lượng của vật. Định luật này thường được phát biểu dưới dạng phương trình a=F/m, với F là lực tác dụng lên vật, m là khối lượng của vật và a là gia tốc của vật đó.\nĐịnh luật III: Khi một vật tác dụng lực lên vật thể thứ hai, vật thứ hai sẽ tác dụng một lực cùng độ lớn và ngược chiều lên vật thứ nhất.\nCả ba định luật được nhà vật lý học Isaac Newton tìm ra lần đầu tiên và được xuất bản trong cuốn sách Philosophiæ Naturalis Principia Mathematica (Các nguyên lý toán học của triết học tự nhiên) năm 1687. Newton dùng những định luật này để giải thích và nghiên cứu chuyển động của các vật thể, ví dụ như chuyển động của các hành tinh trong hệ mặt trời. Trong các thập niên tiếp theo, các giới hạn của các định luật của Newton đã được khám phá, và các lý thuyết mới đã được phát triển, ví dụ như cơ học lượng tử và lý thuyết tương đối, để giải quyết các vấn đề vật lý trong những trường hợp cực đoan."},{"pageNumber":3,"text":"Tổng quan\nCác định luật chuyển động của Newton đều được áp dụng cho các vật thể được lý tưởng hóa thành các chất điểm với kích thước vô cùng nhỏ so với quỹ đạo của nó. Do vậy, các định luật này có thể áp dụng được cả với các ngôi sao và các hành tinh, khi mà kích thước của các vật thể rất lớn nhưng vẫn có thể coi là các chất điểm nếu so sánh với quỹ đạo của chúng.\nBan đầu, các định luật của Newton không thể sử dụng được với chuyển động của các vật rắn hoặc các vật thể có khối lượng biến đổi. Năm 1750, Leonard Euler tổng quát hoá các định luật của Newton và đưa ra Các định luật về chuyển động của Euler. Nếu như một vật rắn được biểu thị như tập hợp của vô số chất điểm thì định luật của Euler có thể được coi là một hệ quả của định luật Newton. Tuy nhiên, các định luật của Euler có thể áp dụng cho chuyển động của các vật thể mà không cần biết đến hình dáng của vật thể.\n\nĐịnh luật I\n\nPhát biểu\nĐịnh luật I của Newton được phát biểu như sau:\n\nĐịnh luật có thể viết dưới dạng lý học:\n\n∑𝐅=0⇒d𝐯dt=0.\n\nLịch sử"},{"pageNumber":4,"text":"Nhà khoa học Hy Lạp cổ Aristotle tin rằng tất cả mọi thứ đều có vị trí riêng của nó trong vũ trụ. Những vật nặng như hòn đá hay cây cỏ do vậy sẽ có xu hướng ở lại Trái Đất, còn những vật nhẹ như lửa hay không khí sẽ có xu hướng ở trên không trung và những ngôi sao sẽ có xu hướng ở trên thiên đường. Từ đó, Aristotle cho rằng mọi vật thể đều ở trạng thái ban đầu là trạng thái nghỉ (trạng thái trong vị trí của nó), do vậy để một vật thể chuyển động thẳng đều, cần phải có một lực không đổi tác dụng vào vật trong suốt quá trình chuyển động.\nTuy nhiên, Galileo Galilei cho rằng không cần đến lực để vật thể di chuyển thẳng đều. Theo Gallilei, một vật chuyển động luôn có khuynh hướng giữ nguyên trạng thái chuyển động (quán tính) của nó. Trạng thái chuyển động ở đây được đặc trưng bởi vận tốc (hay tổng quát là động lượng) của chuyển động. Nếu không chịu tác dụng bởi một tổng lực khác không thì một vật đang đứng yên sẽ đứng yên mãi mãi, và một vật đang chuyển động sẽ chuyển động thẳng đều mãi mãi. Định luật I của Newton được bắt nguồn từ định luật quán tính của Galilei và được mở rộng cho trường hợp tổng các lực bằng 0.\nCùng thời với Newton, nhiều nhà khoa học khác cũng đã phát biểu định luật quán tính, tiêu biểu như Thomas Hobbes  và René Descartes.\n\nÝ Nghĩa"},{"pageNumber":5,"text":"Định luật I chỉ ra rằng lực không phải là nguyên nhân cơ bản gây ra chuyển động của các vật, mà đúng hơn là nguyên nhân gây ra sự thay đổi trạng thái chuyển động (thay đổi vận tốc/động lượng của vật).\nNếu không xét tới các lực quán tính, định luật I của Newton chỉ nghiệm đúng trong các hệ quy chiếu quán tính, tức là hệ quy chiếu có vận tốc không đổi so với nhau. Nói cách khác, định luật I tiên đoán sự tồn tại của ít nhất một hệ quy chiếu quán tính, trong đó vật thể không thay đổi vận tốc nếu như tổng các lực tác dụng lên nó bằng 0. Nếu áp dụng định luật này đối với các hệ quy chiếu phi quán tính, chúng ta phải thêm vào lực quán tính. Khi đó, tổng lực bằng lực cơ bản cộng lực quán tính. Như vậy, định luật I Newton còn có thể phát biểu dưới dạng:\n\nTrong mọi vũ trụ hữu hình, chuyển động của một chất điểm trong một hệ quy chiếu cho trước Φ sẽ được quyết định bởi tác động của các lực luôn triệt tiêu nhau khi và chỉ khi vân tốc của chất điểm đó bất biến trong Φ. Nói cách khác, một chất điểm luôn ở trạng thái đứng yên hoặc chuyển động thẳng đều trong hệ quy chiếu Φ trừ khi có một ngoại lực khác 0 tác động lên chất điểm đó"},{"pageNumber":6,"text":"Trong thực tế, không có hệ quy chiếu nào là hệ quy chiếu quán tính hoàn toàn. Tuy nhiên, trong nhiều trường hợp cụ thể, một hệ quy chiếu có thể coi gần đúng là hệ quy chiếu quán tính. Ví dụ, khi xét chuyển động của các vật trên bề mặt Trái đất, người ta thường xem hệ quy chiếu gắn với mặt đất như một hệ quy chiếu quán tính.\n\nĐịnh luật II\n\nPhát biểu\nĐịnh luật II phát biểu như sau:\n\nĐịnh luật có thể viết dưới dạng toán học:\n\ndp→dt=F→.\nVới:\n\nF→ là tổng ngoại lực tác dụng lên vật (trong SI, lực đo bằng đơn vị N)\np→ là động lượng của vật (trong SI, động lượng đo bằng đơn vị kg m/s)\nt là thời gian (trong SI, thời gian đo bằng đơn vị s)\n\nÝ nghĩa\n\nTheo phát biểu ban đầu của Newton, xung lực J được hiểu như là tích phân của một ngoại lực F trong khoảng thời gian Δt:\n𝐉=∫Δt𝐅dt.\nTừ đó ta có:\n𝐉=𝐅dt=d𝐩. hay:\n𝐅=d𝐩dt=d(m𝐯)dt.\nBởi vì chủ yếu các vật thể sẽ có khối lượng không thay đổi, định luật thường được biết đến dưới dạng:\n\nNguồn tài liệu mở: https://vi.wikipedia.org/wiki/C%C3%A1c_%C4%91%E1%BB%8Bnh_lu%E1%BA%ADt_chuy%E1%BB%83n_%C4%91%E1%BB%99ng_c%E1%BB%A7a_Newton (CC BY-SA 4.0)"}]'::jsonb,
  'published'
